let latest = 0;
async function search(q) {
  const id = ++latest;
  try {
    const r = await fetch('/api/search?q=' + encodeURIComponent(q));
    if (!r.ok) throw new Error('Failed');
    const data = await r.json();
    if (id === latest) console.log(data);
  } catch(e) { if (id === latest) console.error(e); }
}
